INSERT OR IGNORE INTO "integrations" ("id","name","source_product_id","target_product_id","mechanism_kind","mechanism_name","direction","built_by_vendor_id","powered_by_product_id","description","listing_url","docs_url","website","mechanism_url","pricing_model","maturity","notes","last_reviewed_at","maintained_by","created_at","updated_at") VALUES ('4dc9d4bb-494f-4735-8ebb-7cc5389048ce','Polycam ↔ AutoCAD','3fc2e59a-58de-4550-ab5d-e09070227988','0db69a52-a372-47a8-8cf3-44866d0de2f0','native','DXF export (layered floor plan + point cloud)','one-way','a184c0c8-3a1a-4294-8d5c-ba4d700c5abc',NULL,'Polycam exports Space Mode captures as DXF — a point cloud plus a layered 2D floor plan with walls, openings, fixtures and room labels on separate named layers — which drafters open directly in AutoCAD as the base for an as-built plan.','https://learn.poly.cam/hc/en-us/articles/41491709457684-How-to-Export-Polycam-Space-Mode-Captures-to-AutoCAD','https://learn.poly.cam/hc/en-us/articles/27466060715156-Polycam-to-AutoCAD-Workflow-Tutorial',NULL,NULL,NULL,NULL,'Discovered via the vendor help centre on 2026-08-09. Body-checked: the guide is Polycam-specific (names the DXF export column, the "Poly Rooms" layer produced by Polycam''s floor-plan algorithm, and unit handling between the two apps), so this is a documented data path rather than a generic "you can open a DXF" claim. One-way, file-based; no live connector and nothing returns from AutoCAD.

HUMAN DECISION PENDING (accuracy audit 2026-08-09) — edge deliberately KEPT, but the bar is a judgement call, not a fact. The mechanism here is a manual file hand-off: a user exports a DXF and opens it in AutoCAD. It was admitted on the strength of DOCUMENTATION SPECIFICITY (Polycam-named artifacts in the vendor''s step-by-step guide), while the Polycam→Revit candidate was parked for having only a one-line video stub — even though the underlying mechanism is identical in both cases. If the catalog''s bar is "purpose-built mechanism" rather than "documented, product-specific data path", this edge and Polycam↔ArcGIS should both be retracted and only SketchUp (first-party extension) and Xactimate (paid ESX export) kept. Conversely, if documentation quality is the bar, Polycam↔Revit deserves to be added for consistency. Curator to rule; noted rather than silently resolved.',NULL,'aeci','2026-08-09T03:03:40.553Z','2026-08-09T03:03:40.553Z');
INSERT OR IGNORE INTO "integrations" ("id","name","source_product_id","target_product_id","mechanism_kind","mechanism_name","direction","built_by_vendor_id","powered_by_product_id","description","listing_url","docs_url","website","mechanism_url","pricing_model","maturity","notes","last_reviewed_at","maintained_by","created_at","updated_at") VALUES ('74099c42-e67a-4bab-9053-f6320b17e5ef','Polycam ↔ ArcGIS','3fc2e59a-58de-4550-ab5d-e09070227988','b211276b-bf99-4ef2-bb3d-146728070056','native','Georeferenced LAS/LAZ export','one-way','a184c0c8-3a1a-4294-8d5c-ba4d700c5abc',NULL,'Polycam exports georeferenced LAS/LAZ point clouds (WGS 1984) that survey and GIS teams convert and load into ArcGIS Pro as LAS datasets and point-cloud scene layers for 3D visualisation and analysis.','https://learn.poly.cam/hc/en-us/articles/34587812341780-Polycam-ESRI-ArcGIS-Import-Guide',NULL,NULL,NULL,NULL,NULL,'Discovered via the vendor help centre on 2026-08-09. Body-checked: step-by-step vendor guide covering the LAZ→LAS conversion ArcGIS Pro requires, the WGS 1984 coordinate system Polycam captures in, symbology and Create Point Cloud Scene Layer. Requires an ArcGIS Pro Standard/Advanced licence with 3D Analyst + Image Analyst; georeferenced export requires a Polycam Business plan. One-way, file-based.

HUMAN DECISION PENDING (accuracy audit 2026-08-09) — edge deliberately KEPT; same bar question as Polycam↔AutoCAD (rec x2Fe7vQTmi0Rv2). This is a manual file hand-off admitted on documentation specificity, not a live connector. If the bar tightens to "purpose-built mechanism", retract both; if it stays at "documented product-specific data path", Polycam↔Revit should be added for consistency.

TARGET GRANULARITY: the evidence guide is specifically about ArcGIS Pro (desktop, needing 3D Analyst + Image Analyst extensions), but this edge points at the umbrella Esri ArcGIS platform record because no ArcGIS Pro product exists in the catalog. Acceptable for now; re-point if ArcGIS Pro is ever seeded as its own product.',NULL,'aeci','2026-08-09T03:03:40.553Z','2026-08-09T03:03:40.553Z');
